CREATE OR REPLACE FUNCTION check_resolution_risk()
RETURNS TRIGGER AS $$
BEGIN
    -- Only check when updating resstat (resolution status)
    IF TG_OP = 'UPDATE' AND OLD.resstat IS DISTINCT FROM NEW.resstat THEN
        -- Check if the associated case has high risk
        IF EXISTS (
            SELECT 1 
            FROM compliancecase cc 
            WHERE cc.compreg = NEW.compref2 
            AND (cc.alertlvl IN ('High', 'Critical'))
        ) THEN
            RAISE EXCEPTION 'Resolution prevented: associated case has high risk level';
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

